    pub(crate) fn compare_firewall_rule(
        &self,
        other: &Document,
        a: &FirewallRule,
        b: &FirewallRule,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        if a.get_bucket_size() != b.get_bucket_size() {
            return Err(format!("{path}: BUCKET_SIZE mismatch"));
        }
        if a.get_data_link_layer_rule() != b.get_data_link_layer_rule() {
            return Err(format!("{path}: DATA_LINK_LAYER_RULE mismatch"));
        }
        if a.get_dds_rule() != b.get_dds_rule() {
            return Err(format!("{path}: DDS_RULE mismatch"));
        }
        if a.get_do_ip_rule() != b.get_do_ip_rule() {
            return Err(format!("{path}: DO_IP_RULE mismatch"));
        }
        if a.get_network_layer_rule() != b.get_network_layer_rule() {
            return Err(format!("{path}: NETWORK_LAYER_RULE mismatch"));
        }
        let list_a = a.get_payload_byte_pattern_rules();
        let list_b = b.get_payload_byte_pattern_rules();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: PAYLOAD_BYTE_PATTERN_RULES length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.payload_byte_pattern_rules.get(*x).ok_or_else(|| {
                format!("{path}.PAYLOAD_BYTE_PATTERN_RULES[{index}]: id not found in own arena")
            })?;
            let y = other.payload_byte_pattern_rules.get(*y).ok_or_else(|| {
                format!("{path}.PAYLOAD_BYTE_PATTERN_RULES[{index}]: id not found in other arena")
            })?;
            self.compare_payload_byte_pattern_rule(
                other,
                x,
                y,
                &format!("{path}.PAYLOAD_BYTE_PATTERN_RULES[{index}]"),
            )?;
        }
        if a.get_refill_amount() != b.get_refill_amount() {
            return Err(format!("{path}: REFILL_AMOUNT mismatch"));
        }
        if a.get_someip_rule() != b.get_someip_rule() {
            return Err(format!("{path}: SOMEIP_RULE mismatch"));
        }
        if a.get_someip_sd_rule() != b.get_someip_sd_rule() {
            return Err(format!("{path}: SOMEIP_SD_RULE mismatch"));
        }
        if a.get_transport_layer_rule() != b.get_transport_layer_rule() {
            return Err(format!("{path}: TRANSPORT_LAYER_RULE mismatch"));
        }
        Ok(())
    }

